-- Init SQL for NextGame: create table and insert games from db.json
-- Init SQL for NextGame: create table and insert games
CREATE TABLE IF NOT EXISTS games (
  id INTEGER PRIMARY KEY,
  name TEXT,
  genre TEXT,
  difficulty TEXT,
  mood TEXT,
  description TEXT,
  image TEXT,
  keywords JSONB
);

-- Table to persist Steam enrichment/cache
CREATE TABLE IF NOT EXISTS steam_enrichments (
  game_id INTEGER REFERENCES games(id) ON DELETE CASCADE,
  appid INTEGER,
  data JSONB,
  fetched_at TIMESTAMP,
  PRIMARY KEY (game_id)
);

-- If tables exist, truncate both (use CASCADE to avoid FK ordering issues)
TRUNCATE TABLE steam_enrichments, games CASCADE;

